export default JSON.parse("{\"id\":\"interpersonal_effectiveness_handout_16c\",\"module\":\"Interpersonal Effectiveness\",\"module_category\":\"Interpersonal Effectiveness Skills\",\"item_type\":\"handout\",\"item_number\":\"16c\",\"title\":\"Identifying Dialectics For each group, check the most dialectical response. \uf8f1\u2022 \uf8f4\u2022\",\"source_marker\":\"Interpersonal Effectiveness Handout 16c\",\"source_pdf\":\"DBT Skills Workbook.pdf\",\"source_pdf_pages\":[178],\"source_book_pages\":[\"154\"],\"related_references\":[],\"is_example\":false,\"fillable_html_created\":false,\"keywords\":[\"Dialectics\",\"Identifying\",\"check\",\"dialectical\",\"each\",\"group\",\"most\",\"response\"],\"pages\":[{\"pdf_page\":178,\"book_page\":\"154\",\"text\":\"154\\nFrom DBT Skills Training Handouts and Worksheets, Second Edition by Marsha M. Linehan. Copyright 2015 by Marsha M. Linehan. Permission\\nto photocopy this handout is granted to purchasers of this book for personal use only (see copyright page for details).\\nInterpersonal Effectiveness Handout 16c\\nIdentifying Dialectics\\nFor each group, check the most dialectical response.\\n\uf8f1\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f2\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f3\\n\\u0003\\n\u0089 1A.\\tPay attention to your effect on others.\\n\\u0003\\n\u0089 1B.\\tAssume that others\u2019 reactions to you\\nare unrelated to your treatment of\\nthem.\\n\uf8f1\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f2\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f3\\n\\u0003\\n\u0089 5A.\\tExamine a difficult relationship by\\nlooking at how the interactions over\\ntime between you and the other\\nperson may be problematic.\\n\\u0003\\n\u0089 5B.\\tAssume that difficulties in a\\nrelationship are caused completely by\\nyou or by the other person.\\n\uf8f1\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f2\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f3\\nSaying:\\n\\u0003\\n\u0089 2A.\\t\u201cI know I am right about this.\u201d\\n\\u0003\\n\u0089 2B.\\t\u201cI can see your point of view, even\\nthough I do not agree with it.\u201d\\n\\u0003\\n\u0089 2C.\\t\u201cThe way you are thinking doesn\u2019t\\nmake any sense.\u201d\\n\uf8f1\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f2\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f3\\nSaying:\\n\\u0003\\n\u0089 6A.\\t\u201cIt is hopeless. I cannot do it.\u201d\\n\\u0003\\n\u0089 6B.\\t\u201cThis is a breeze. I\u2019ve got no\\nproblems.\u201d\\n\\u0003\\n\u0089 6C.\\t\u201cThis is really hard for me, and I am\\ngoing to keep trying.\u201d\\n\uf8f1\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f2\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f3\\nSaying:\\n\\u0003\\n\u0089 3A.\\t\u201cEveryone always treats me unfairly.\u201d\\n\\u0003\\n\u0089 3B.\\t\u201cI believe the coach should reconsider\\nhis decision to cut me from the team.\u201d\\n\\u0003\\n\u0089 3C.\\t\u201cCoaches know best who to keep on\\nteams and who to cut.\u201d\\n\uf8f1\u2022\uf8f4\u2022\uf8f4\u2022\uf8f4\u2022\uf8f2\u2022\uf8f4\u2022\uf8f4\u2022\uf8f4\u2022\uf8f3\\n\\u0003\\n\u0089 7A.\\tWhen you disagree with someone,\\nbe sure and be very clear about your\\npoint of view.\\n\\u0003\\n\u0089 7B.\\tWhen you disagree with someone, try\\nand see their point of view.\\n\uf8f1\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f2\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f3\\n\\u0003\\n\u0089 4A.\\tJudge friends as disloyal and uncaring\\nif they start changing in ways you don\u2019t\\nlike.\\n\\u0003\\n\u0089 4B.\\tAccept that interests change.\\n\uf8f1\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f2\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f3\\n\\u0003\\n\u0089 8A.\\tDemand that relationships be stable\\nwithout changing.\\n\\u0003\\n\u0089 8B.\\tEmbrace change and see it as\\ninevitable.\\nNote. Adapted in part from Miller, A. L., Rathus, J. H., & Linehan, M. M. (2007). Dialectical behavior therapy with suicidal adolescents. New York:\\nGuilford Press. Copyright 2007 by The Guilford Press. Adapted by permission.\"}],\"full_text\":\"Interpersonal Effectiveness Handout 16c\\nIdentifying Dialectics\\nFor each group, check the most dialectical response.\\n\uf8f1\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f2\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f3\\n\\u0003\\n\u0089 1A.\\tPay attention to your effect on others.\\n\\u0003\\n\u0089 1B.\\tAssume that others\u2019 reactions to you\\nare unrelated to your treatment of\\nthem.\\n\uf8f1\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f2\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f3\\n\\u0003\\n\u0089 5A.\\tExamine a difficult relationship by\\nlooking at how the interactions over\\ntime between you and the other\\nperson may be problematic.\\n\\u0003\\n\u0089 5B.\\tAssume that difficulties in a\\nrelationship are caused completely by\\nyou or by the other person.\\n\uf8f1\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f2\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f3\\nSaying:\\n\\u0003\\n\u0089 2A.\\t\u201cI know I am right about this.\u201d\\n\\u0003\\n\u0089 2B.\\t\u201cI can see your point of view, even\\nthough I do not agree with it.\u201d\\n\\u0003\\n\u0089 2C.\\t\u201cThe way you are thinking doesn\u2019t\\nmake any sense.\u201d\\n\uf8f1\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f2\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f3\\nSaying:\\n\\u0003\\n\u0089 6A.\\t\u201cIt is hopeless. I cannot do it.\u201d\\n\\u0003\\n\u0089 6B.\\t\u201cThis is a breeze. I\u2019ve got no\\nproblems.\u201d\\n\\u0003\\n\u0089 6C.\\t\u201cThis is really hard for me, and I am\\ngoing to keep trying.\u201d\\n\uf8f1\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f2\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f3\\nSaying:\\n\\u0003\\n\u0089 3A.\\t\u201cEveryone always treats me unfairly.\u201d\\n\\u0003\\n\u0089 3B.\\t\u201cI believe the coach should reconsider\\nhis decision to cut me from the team.\u201d\\n\\u0003\\n\u0089 3C.\\t\u201cCoaches know best who to keep on\\nteams and who to cut.\u201d\\n\uf8f1\u2022\uf8f4\u2022\uf8f4\u2022\uf8f4\u2022\uf8f2\u2022\uf8f4\u2022\uf8f4\u2022\uf8f4\u2022\uf8f3\\n\\u0003\\n\u0089 7A.\\tWhen you disagree with someone,\\nbe sure and be very clear about your\\npoint of view.\\n\\u0003\\n\u0089 7B.\\tWhen you disagree with someone, try\\nand see their point of view.\\n\uf8f1\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f2\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f3\\n\\u0003\\n\u0089 4A.\\tJudge friends as disloyal and uncaring\\nif they start changing in ways you don\u2019t\\nlike.\\n\\u0003\\n\u0089 4B.\\tAccept that interests change.\\n\uf8f1\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f2\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f3\\n\\u0003\\n\u0089 8A.\\tDemand that relationships be stable\\nwithout changing.\\n\\u0003\\n\u0089 8B.\\tEmbrace change and see it as\\ninevitable.\\nNote. Adapted in part from Miller, A. L., Rathus, J. H., & Linehan, M. M. (2007). Dialectical behavior therapy with suicidal adolescents. New York:\\nGuilford Press. Copyright 2007 by The Guilford Press. Adapted by permission.\",\"copyright_notice\":\"Extracted from user-provided PDF: DBT Skills Training Handouts and Worksheets, Second Edition by Marsha M. Linehan. Respect source copyright and purchaser-use limits.\",\"created_at\":\"2026-06-25T17:33:54\",\"json_path\":\"json/items/interpersonal_effectiveness/handouts/interpersonal_effectiveness_handout_16c_identifying_dialectics_for_each_group_check_the_most_dialectical_respo.json\",\"ourspace_shared_life_filter\":{\"revision_id\":\"ourspace_shared_life_filter_v1\",\"title\":\"Identifying Dialectics For each group, check the most dialectical response. \uf8f1\u2022 \uf8f4\u2022\",\"domain\":\"interpersonal_effectiveness\",\"item_type\":\"handout\",\"shared_facing_summary\":\"Use this to protect both people: needs are real, boundaries are kind, and a pause is not abandonment when repair is named.\",\"tiny_steps\":[\"Name the ask in one sentence.\",\"Name capacity honestly.\",\"Offer one smaller option.\",\"Agree on a return time or next check-in.\"],\"flare_day_versions\":{\"minimum\":\"One breath, one label, one safe message, or one checkbox.\",\"medium\":\"Two to five minutes with everything reachable from bed/chair.\",\"full\":\"Use the original worksheet/handout when both bodies and brains have capacity.\"},\"accessibility_modifications\":[\"Add reassurance before hard asks.\",\"Use text/chat if speech is hard.\",\"Include caregiver capacity as part of the plan, not an afterthought.\"],\"relationship_and_caregiver_notes\":[\"William's needs and Jasper's capacity both count.\",\"Ask before helping; ask before escalating; name the smallest next step.\",\"Pause means pause, not abandonment. I am coming back. I care about us. I need a smaller next step.\",\"What is needed, what capacity exists, what can be smaller, and what can wait?\"],\"identity_and_trauma_filter\":[\"Use William's masculine language and Jasper's they/them language.\",\"Use consent-based, non-shaming, body-neutral language unless a person has explicitly chosen a term.\",\"Do not turn symptoms, dysphoria, trauma responses, clutter, fatigue, or emotional intensity into moral failure.\"],\"avoid_or_adjust\":[\"Do not use skills to win, corner, threaten leaving, or make either person prove pain or disability.\"],\"suggested_cadence\":[\"as_needed\",\"weekly_repair_check\"],\"app_tags\":[\"adhd_friendly\",\"disability_first\",\"interpersonal_effectiveness\",\"shared\",\"tiny_steps\",\"trauma_informed\"]},\"ourspace_shared_revision_metadata\":{\"source_path\":\"DBT+ADHD Skill Files/03_DBT_Interpersonal_Effectiveness/handouts/json/interpersonal_effectiveness_handout_16c_identifying_dialectics_for_each_group_check_the_most_dialectical_respo.json\",\"shared_output_path\":\"shared/03_dbt_interpersonal_effectiveness/handouts_json/interpersonal_effectiveness_handout_16c_identifying_dialectics_for_each_g_6e2cbffa.json\",\"revised_at_utc\":\"2026-06-26T00:24:16Z\",\"copyright_note\":\"Extracted from user-provided PDF: DBT Skills Training Handouts and Worksheets, Second Edition by Marsha M. Linehan. Respect source copyright and purchaser-use limits.\"},\"shared_json_path\":\"shared/03_dbt_interpersonal_effectiveness/handouts_json/interpersonal_effectiveness_handout_16c_identifying_dialectics_for_each_g_6e2cbffa.json\"}");
